import { fetchGcpSecretsManagerSecrets, gcpWhoami } from './index';
import type { SecretManagerNetworkConfig } from '../resolve-agents';

// The Google SDK, auth library and agent factory are all mocked, so these tests cover the wiring
// this module owns — credential checks, project id validation, agent installation and per-project
// fan-out — without any real network, credential or proxy work.
jest.mock('@google-cloud/secret-manager');
jest.mock('google-auth-library');
jest.mock('../../../utils/http-https-agents');

const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const { GoogleAuth, gaxios } = require('google-auth-library');
const { getHttpHttpsAgents } = require('../../../utils/http-https-agents');

const httpsAgent = { id: 'https-agent' };
const httpAgent = { id: 'http-agent' };

const gcpConfig = {
  clientEmail: 'sa@test-project.iam.gserviceaccount.com',
  privateKey: 'test-key'
};

const networkConfig: SecretManagerNetworkConfig = { options: { shouldVerifyTls: false } } as SecretManagerNetworkConfig;

// listSecretsAsync yields fully qualified resource names; the fetch path keeps only the trailing id.
// Call this once per listSecretsAsync invocation — an async generator object can only be consumed
// once, so a shared instance would come back empty for the second project.
const asyncIterableOf = (projectId: string, names: string[]) =>
  (async function* () {
    for (const name of names) {
      yield { name: `projects/${projectId}/secrets/${name}` };
    }
  })();

// The Google modules are `require`d lazily inside the module under test, so every describe has to
// re-stub them after clearAllMocks. Pass an array to collect the interceptors the module installs
// on the transporter it builds; the transport tests below replay them by hand.
const stubGoogleAuth = (requestInterceptors?: any[]) => {
  gaxios.Gaxios = jest.fn().mockImplementation(() => ({
    interceptors: {
      request: { add: (interceptor: any) => requestInterceptors?.push(interceptor) }
    }
  }));
  GoogleAuth.mockImplementation((opts: any) => ({ type: 'google-auth', opts }));
};

// The form validates these fields, but the CLI's --secrets-env-file path doesn't, so the failure has
// to be caught here rather than being left to surface in the Google SDK's own wording.
describe('GCP Secrets Manager - credential validation', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    stubGoogleAuth();
  });

  const incompleteConfigs: [string, any][] = [
    ['a missing client email', { privateKey: 'test-key' }],
    ['a missing private key', { clientEmail: 'sa@test-project.iam.gserviceaccount.com' }],
    ['a whitespace-only private key', { clientEmail: 'sa@test-project.iam.gserviceaccount.com', privateKey: '  ' }],
    ['no config at all', undefined]
  ];

  it.each(incompleteConfigs)('should reject %s without constructing a GoogleAuth', async (_label, config) => {
    await expect(
      fetchGcpSecretsManagerSecrets({ gcpConfig: config, projectIds: ['project-a'] })
    ).rejects.toThrow('GCP service account requires both a client email and a private key');

    expect(GoogleAuth).not.toHaveBeenCalled();
  });

  it('should fail the credential check rather than report success for an incomplete config', async () => {
    await expect(gcpWhoami({ config: { gcpConfig: {} } })).rejects.toThrow(
      'GCP service account requires both a client email and a private key'
    );

    expect(GoogleAuth).not.toHaveBeenCalled();
  });

  // Minting a token is what actually proves the service-account key is usable, so the check has to
  // name a scope itself — unlike the fetch path, no SecretManagerServiceClient supplies defaults here.
  it('should mint a scoped access token to confirm the credentials are usable', async () => {
    GoogleAuth.mockImplementation((opts: any) => ({
      opts,
      getClient: async () => ({ getAccessToken: async () => ({ token: 'ya29.token' }) })
    }));

    await expect(gcpWhoami({ config: { gcpConfig } })).resolves.toEqual({
      status: 'success',
      message: 'GCP credentials are valid'
    });
    expect(GoogleAuth.mock.calls[0][0].scopes).toEqual(['https://www.googleapis.com/auth/cloud-platform']);
  });

  it('should reject when the token exchange returns no token', async () => {
    GoogleAuth.mockImplementation(() => ({
      getClient: async () => ({ getAccessToken: async () => ({}) })
    }));

    await expect(gcpWhoami({ config: { gcpConfig } })).rejects.toThrow(
      'No access token was returned for these credentials'
    );
  });

  // The SDK's rejection reason is surfaced as-is: it names the actual problem (a malformed key, a
  // disabled service account) far better than any wording this module could substitute.
  it('should surface the reason the token exchange failed', async () => {
    GoogleAuth.mockImplementation(() => ({
      getClient: async () => {
        throw new Error('error:1E08010C:DECODER routines::unsupported');
      }
    }));

    await expect(gcpWhoami({ config: { gcpConfig } })).rejects.toThrow(
      'error:1E08010C:DECODER routines::unsupported'
    );
  });

  it('should fall back to a generic message when the failure carries none', async () => {
    GoogleAuth.mockImplementation(() => ({
      getClient: async () => {
        throw { code: 'ENOTFOUND' };
      }
    }));

    await expect(gcpWhoami({ config: { gcpConfig } })).rejects.toThrow('Failed to validate GCP credentials');
  });
});

// google-gax overwrites `agent` on every fallback-REST request, so a gaxios request interceptor is
// the only place the caller's proxy/TLS agents can be applied. These tests replay that interceptor
// the way gaxios would, since nothing else in the suite exercises it.
describe('GCP Secrets Manager - transport wiring', () => {
  let requestInterceptors: any[];

  beforeEach(() => {
    jest.clearAllMocks();
    requestInterceptors = [];
    stubGoogleAuth(requestInterceptors);
    getHttpHttpsAgents.mockResolvedValue({ httpAgent, httpsAgent });

    SecretManagerServiceClient.mockImplementation(() => ({
      listSecretsAsync: jest.fn().mockImplementation(async function* () {}),
      accessSecretVersion: jest.fn()
    }));
  });

  // Runs the fetch path only to build the auth object, then returns the interceptor it installed.
  const installedInterceptor = async () => {
    await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a'], networkConfig });
    return requestInterceptors[0];
  };

  it.each([
    ['https', 'https://secretmanager.googleapis.com/v1/projects/project-a/secrets', httpsAgent],
    ['http', 'http://secretmanager.internal/v1/projects/project-a/secrets', httpAgent]
  ])('should attach the %s agent to an outgoing request', async (_scheme, url, expectedAgent) => {
    const interceptor = await installedInterceptor();

    await expect(interceptor.resolved({ url })).resolves.toEqual({ url, agent: expectedAgent });
  });

  // Agents are resolved per request URL rather than once, so proxy-bypass rules are evaluated
  // against each target — the OAuth token endpoint and the Secret Manager endpoint differ.
  it('should resolve agents against the request url and the caller\'s network config', async () => {
    const interceptor = await installedInterceptor();

    await interceptor.resolved({ url: 'https://oauth2.googleapis.com/token' });

    expect(getHttpHttpsAgents).toHaveBeenLastCalledWith({
      requestUrl: 'https://oauth2.googleapis.com/token',
      ...networkConfig
    });
  });

  // With no proxy or custom TLS configured there is no agent to attach, and setting `agent:
  // undefined` would override gax's own keep-alive agent with nothing.
  it('should leave the request untouched when no agent is resolved', async () => {
    getHttpHttpsAgents.mockResolvedValue({});
    const interceptor = await installedInterceptor();

    const config = await interceptor.resolved({ url: 'https://secretmanager.googleapis.com/v1' });

    expect(config).not.toHaveProperty('agent');
  });

  // REST mode is load-bearing: a Node http(s) agent cannot be attached to a gRPC channel, so
  // dropping this would make the interceptor above pointless.
  it('should create the client in fallback-REST mode with the proxy-aware auth', async () => {
    await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a'], networkConfig });

    expect(SecretManagerServiceClient).toHaveBeenCalledWith({
      auth: expect.objectContaining({ type: 'google-auth' }),
      fallback: 'rest'
    });
  });

  // SecretManagerServiceClient sets its own `defaultScopes` on the GoogleAuth object while
  // constructing; naming scopes here would pre-empt them. Only gcpWhoami passes scopes.
  it('should leave scopes unset on the fetch path', async () => {
    await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a'], networkConfig });

    expect(GoogleAuth.mock.calls[0][0]).not.toHaveProperty('scopes');
  });

  it('should pass the service account credentials through to GoogleAuth', async () => {
    await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a'], networkConfig });

    expect(GoogleAuth.mock.calls[0][0].credentials).toEqual({
      client_email: gcpConfig.clientEmail,
      private_key: gcpConfig.privateKey
    });
  });
});

describe('GCP Secrets Manager - project id validation', () => {
  let mockClient: any;

  beforeEach(() => {
    jest.clearAllMocks();
    stubGoogleAuth();
    getHttpHttpsAgents.mockResolvedValue({});

    mockClient = {
      listSecretsAsync: jest.fn().mockImplementation(async function* () {}),
      accessSecretVersion: jest.fn()
    };
    SecretManagerServiceClient.mockImplementation(() => mockClient);
  });

  // A project id is interpolated into `projects/<id>/secrets/...`, which becomes a URL path in
  // fallback-REST mode; any of these would either rewrite that path or is simply not a valid id.
  it.each([
    ['rewrites the path via traversal', '../../foo'],
    ['contains a slash', 'proj/secrets'],
    ['contains a fragment', 'proj#x'],
    ['contains a query', 'proj?x=1'],
    // A colon is only valid after a dotted domain prefix (legacy domain-scoped ids).
    ['contains a colon without a domain prefix', 'proj:name'],
    ['has a domain prefix with an empty label', 'example..com:my-project'],
    ['has a domain prefix without a dot', 'examplecom:my-project'],
    ['contains a space', 'has space'],
    ['contains uppercase', 'MyProject'],
    ['starts with a digit', '1abcdef'],
    ['starts with a hyphen', '-leading'],
    ['ends with a hyphen', 'trailing-'],
    ['is shorter than 6 chars', 'abcde'],
    ['is longer than 30 chars', 'a' + 'b'.repeat(30)],
    ['is empty', '']
  ])('rejects a project id that %s', async (_label, projectId) => {
    const results = await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: [projectId] });

    expect(results).toEqual([{ projectId, error: 'Invalid GCP project id' }]);
    expect(mockClient.listSecretsAsync).not.toHaveBeenCalled();
  });

  it.each([
    ['a minimum-length id', 'abcdef'],
    ['a maximum-length id', 'a' + 'b'.repeat(28) + 'c'],
    ['a hyphenated id', 'my-project-1'],
    ['an id with consecutive hyphens', 'my--project'],
    // Secret Manager accepts a project number in place of an id, so bare digits must stay usable.
    ['a project number', '123456789012'],
    // Legacy domain-scoped ids (pre-2016 Google Apps projects) carry a `domain:` prefix.
    ['a legacy domain-scoped id', 'example.com:my-project'],
    ['a legacy domain-scoped id with a subdomain', 'sub.example.co.in:my-project']
  ])('accepts %s and fetches its secrets', async (_label, projectId) => {
    const results = await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: [projectId] });

    expect(results).toEqual([{ projectId, data: {} }]);
    expect(mockClient.listSecretsAsync).toHaveBeenCalledWith({ parent: `projects/${projectId}` });
  });

  // Ids come from user-entered table rows and variable interpolation, so stray whitespace is common
  // and would otherwise be reported as an invalid id.
  it('trims surrounding whitespace before validating an id', async () => {
    const results = await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['  my-project  '] });

    expect(results).toEqual([{ projectId: 'my-project', data: {} }]);
    expect(mockClient.listSecretsAsync).toHaveBeenCalledWith({ parent: 'projects/my-project' });
  });

  it('returns no results when no projects are requested', async () => {
    await expect(fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: undefined as any })).resolves.toEqual([]);
    expect(mockClient.listSecretsAsync).not.toHaveBeenCalled();
  });

  it('rejects only the invalid ids while still fetching the valid ones', async () => {
    const results = await fetchGcpSecretsManagerSecrets({
      gcpConfig,
      projectIds: ['good-project', 'proj#x']
    });

    expect(results).toEqual([
      { projectId: 'good-project', data: {} },
      { projectId: 'proj#x', error: 'Invalid GCP project id' }
    ]);
    expect(mockClient.listSecretsAsync).toHaveBeenCalledTimes(1);
  });
});

describe('GCP Secrets Manager - per-project fetch', () => {
  let mockClient: any;

  beforeEach(() => {
    jest.clearAllMocks();
    stubGoogleAuth();
    getHttpHttpsAgents.mockResolvedValue({});

    mockClient = {
      listSecretsAsync: jest.fn(),
      accessSecretVersion: jest.fn()
    };
    SecretManagerServiceClient.mockImplementation(() => mockClient);
  });

  const payloadFor = (value: string) => [{ payload: { data: Buffer.from(value) } }];

  it('should nest each project\'s secrets under its own result, keyed by secret id', async () => {
    mockClient.listSecretsAsync.mockImplementation(({ parent }: any) =>
      parent === 'projects/project-a'
        ? asyncIterableOf('project-a', ['db-password'])
        : asyncIterableOf('project-b', ['api-key'])
    );
    mockClient.accessSecretVersion.mockImplementation(({ name }: any) =>
      Promise.resolve(payloadFor(name.includes('db-password') ? 'hunter2' : '{"token":"abc"}'))
    );

    const results = await fetchGcpSecretsManagerSecrets({
      gcpConfig,
      projectIds: ['project-a', 'project-b']
    });

    expect(results).toEqual([
      { projectId: 'project-a', data: { 'db-password': 'hunter2' } },
      { projectId: 'project-b', data: { 'api-key': { token: 'abc' } } }
    ]);
  });

  it('should read the latest version of each secret', async () => {
    mockClient.listSecretsAsync.mockImplementation(() => asyncIterableOf('project-a', ['db-password']));
    mockClient.accessSecretVersion.mockResolvedValue(payloadFor('hunter2'));

    await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a'] });

    expect(mockClient.accessSecretVersion).toHaveBeenCalledWith({
      name: 'projects/project-a/secrets/db-password/versions/latest'
    });
  });

  // A secret whose value happens to be JSON is parsed so callers can reach individual fields as
  // `<row>.<secretId>.<key>`; anything else stays the raw string.
  it.each([
    ['a json object', '{"token":"abc"}', { token: 'abc' }],
    ['a json scalar', '42', 42],
    ['a plain string', 'hunter2', 'hunter2'],
    ['a string that only looks like json', '{not json}', '{not json}']
  ])('should expose %s as-is', async (_label, stored, expected) => {
    mockClient.listSecretsAsync.mockImplementation(() => asyncIterableOf('project-a', ['value']));
    mockClient.accessSecretVersion.mockResolvedValue(payloadFor(stored));

    const results = await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a'] });

    expect(results).toEqual([{ projectId: 'project-a', data: { value: expected } }]);
  });

  it('should expose a secret with no payload as an empty string', async () => {
    mockClient.listSecretsAsync.mockImplementation(() => asyncIterableOf('project-a', ['empty']));
    mockClient.accessSecretVersion.mockResolvedValue([{ payload: {} }]);

    const results = await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a'] });

    expect(results).toEqual([{ projectId: 'project-a', data: { empty: '' } }]);
  });

  // A project can hold thousands of secrets and each one is a separate API call, so reads run
  // through a bounded worker pool rather than all at once.
  it('should read secrets through a bounded worker pool', async () => {
    const secretNames = Array.from({ length: 25 }, (_, i) => `secret-${i}`);
    mockClient.listSecretsAsync.mockImplementation(() => asyncIterableOf('project-a', secretNames));

    let inFlight = 0;
    let peakInFlight = 0;
    mockClient.accessSecretVersion.mockImplementation(async () => {
      peakInFlight = Math.max(peakInFlight, ++inFlight);
      await new Promise((resolve) => setImmediate(resolve));
      inFlight--;
      return payloadFor('value');
    });

    const [result] = await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a'] });

    // Exactly the pool size, not merely at most: an upper bound alone would also hold if the reads
    // ran one at a time, which would make 25 secrets 25 round trips deep.
    expect(Object.keys(result.data!)).toHaveLength(25);
    expect(peakInFlight).toBe(10);
  });

  // Projects are read in sequence so that pool stays the overall ceiling instead of being multiplied
  // by the number of projects: the next project must not start while the previous one is reading.
  it('should read one project at a time', async () => {
    const events: string[] = [];
    mockClient.listSecretsAsync.mockImplementation(({ parent }: any) => {
      events.push(`list ${parent}`);
      return asyncIterableOf(parent.split('/').pop(), ['only-secret']);
    });
    mockClient.accessSecretVersion.mockImplementation(async ({ name }: any) => {
      await new Promise((resolve) => setImmediate(resolve));
      events.push(`read ${name.split('/')[1]}`);
      return payloadFor('value');
    });

    await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a', 'project-b'] });

    expect(events).toEqual([
      'list projects/project-a',
      'read project-a',
      'list projects/project-b',
      'read project-b'
    ]);
  });

  it('should build one client for all projects', async () => {
    mockClient.listSecretsAsync.mockImplementation(({ parent }: any) =>
      asyncIterableOf(parent.split('/').pop(), [])
    );

    await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a', 'project-b'] });

    expect(SecretManagerServiceClient).toHaveBeenCalledTimes(1);
  });

  it('should report a project-level failure on that project only', async () => {
    mockClient.listSecretsAsync.mockImplementation(({ parent }: any) => {
      if (parent === 'projects/missing-project') {
        throw new Error('Permission denied on resource project missing-project');
      }
      return asyncIterableOf('project-b', ['api-key']);
    });
    mockClient.accessSecretVersion.mockResolvedValue(payloadFor('secret-value'));

    const results = await fetchGcpSecretsManagerSecrets({
      gcpConfig,
      projectIds: ['missing-project', 'project-b']
    });

    expect(results).toEqual([
      { projectId: 'missing-project', error: 'Permission denied on resource project missing-project' },
      { projectId: 'project-b', data: { 'api-key': 'secret-value' } }
    ]);
  });

  // The SDK can reject with a non-Error value, which would otherwise leave the row's error blank.
  it('should fall back to a generic message when a project failure carries none', async () => {
    mockClient.listSecretsAsync.mockImplementation(() => {
      throw { code: 7 };
    });

    const results = await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a'] });

    expect(results).toEqual([{ projectId: 'project-a', error: 'Unknown error' }]);
  });

  it('should skip an unreadable secret and keep the rest of the project', async () => {
    mockClient.listSecretsAsync.mockImplementation(() => asyncIterableOf('project-a', ['readable', 'locked']));
    mockClient.accessSecretVersion.mockImplementation(({ name }: any) =>
      name.includes('locked')
        ? Promise.reject(new Error('Permission denied'))
        : Promise.resolve(payloadFor('ok'))
    );

    const results = await fetchGcpSecretsManagerSecrets({ gcpConfig, projectIds: ['project-a'] });

    expect(results).toEqual([{ projectId: 'project-a', data: { readable: 'ok' } }]);
  });
});
